CREATE OR REPLACE FUNCTION public.evaluation_validate_assignment() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE uid text; BEGIN IF TG_OP='UPDATE' AND NEW.leader_ids IS NOT DISTINCT FROM OLD.leader_ids THEN RETURN NEW; END IF; FOREACH uid IN ARRAY NEW.leader_ids LOOP IF NOT EXISTS(SELECT 1 FROM public."Users" WHERE "ID"=uid AND "Role"='Leader' AND coalesce("Status",'Active') NOT IN ('Pending','Suspended')) THEN RAISE EXCEPTION 'Assigned leader unavailable'; END IF; END LOOP; RETURN NEW; END $$;
CREATE TRIGGER evaluation_assignment_guard BEFORE INSERT OR UPDATE ON public."Evaluation_Activities" FOR EACH ROW EXECUTE FUNCTION public.evaluation_validate_assignment();
CREATE OR REPLACE FUNCTION public.evaluation_delete_draft(p_id uuid,p_actor text) RETURNS void LANGUAGE plpgsql SET search_path=public AS $$ DECLARE a public."Evaluation_Activities"; tid text; BEGIN SELECT * INTO a FROM public."Evaluation_Activities" WHERE id=p_id FOR UPDATE; IF NOT FOUND OR a.state<>'Draft' OR EXISTS(SELECT 1 FROM public."Evaluation_Results" WHERE activity_id=p_id) THEN RAISE EXCEPTION 'Draft cannot be deleted'; END IF; IF cardinality(a.team_ids)=0 AND NOT public.evaluation_can(p_actor,a.module,'d','') THEN RAISE EXCEPTION 'Not authorized'; END IF; FOREACH tid IN ARRAY a.team_ids LOOP IF NOT public.evaluation_can(p_actor,a.module,'d',tid) THEN RAISE EXCEPTION 'Team not authorized'; END IF; END LOOP; DELETE FROM public."Evaluation_Criteria" WHERE activity_id=p_id; DELETE FROM public."Evaluation_Activities" WHERE id=p_id; END $$;
DO $$ DECLARE body text; BEGIN SELECT pg_get_functiondef('public.evaluation_save_activity(text,jsonb,jsonb)'::regprocedure) INTO body; body:=replace(body,'IF NOT public.evaluation_can(p_actor,p_activity->>''module'',CASE WHEN old.id IS NULL THEN ''a'' ELSE ''e'' END) THEN','IF jsonb_array_length(p_activity->''team_ids'')=0 AND NOT public.evaluation_can(p_actor,p_activity->>''module'',CASE WHEN old.id IS NULL THEN ''a'' ELSE ''e'' END) THEN'); EXECUTE body; END $$;
REVOKE ALL ON FUNCTION public.evaluation_validate_assignment() FROM PUBLIC,anon,authenticated;